🛠 CS → コマ情報整形




                  Tip



キャラクターシート倉庫 さん上部にある「Tekeyフォーマット出力」をクリック →
全文をコピーして下部エリアにペースト →
「変換」をクリックでTekeyのコマ用に整形された文章が表示されます。



                  インセインにしか対応していません また、自分のセッション周り用のみとして想定しています









  変換

    📋







  textarea,
  .output-container {
    max-width: 650px;
    width: 100%;
    margin: 0 auto;
  }

  button {
    margin: 0.5em 0;
    padding: 0.5em 1em;
    font-size: 10px;
    cursor: pointer;
  }
  .output-container {
    position: relative;
    background: #fff;
    border: 1px solid #ccc;
    padding: 1em;
    margin-top: 1em;
    white-space: pre-wrap;
    font-family: monospace;
  }
  .copy-button {
    position: absolute;
    top: 0.5em;
    right: 0.5em;
    background: #eee;
    border: none;
    padding: 0.3em 0.6em;
    cursor: pointer;
    font-size: 1em;
    border-radius: 4px;
    transition: background 0.2s;
  }
  .copy-button:hover {
    background: #ddd;
  }




function convert() {
  const raw = document.getElementById(&#039;input&#039;).value;
  const lines = raw.split(&#039;\n&#039;);

  let name = &#039;&#039;;
  let special = &#039;&#039;;
  let skills = {
    暴力: &#039;〈〉&#039;, 情動: &#039;〈〉&#039;, 知覚: &#039;〈〉&#039;, 技術: &#039;〈〉&#039;, 知識: &#039;〈〉&#039;, 怪異: []
  };
  let fear = &#039;〈〉&#039;;
  let abilities = [];

  for (let line of lines) {
    if (line.includes(&#039;名前：&#039;)) name = line.split(&#039;名前：&#039;)[1].trim();
    if (line.includes(&#039;好奇心分野には○&#039;)) special = &#039;好奇心&#039;;
    if (line.match(/暴力：/)) skills[&#039;暴力&#039;] = extractSkill(line);
    if (line.match(/情動：/)) skills[&#039;情動&#039;] = extractSkill(line);
    if (line.match(/知覚：/)) skills[&#039;知覚&#039;] = extractSkill(line);
    if (line.match(/技術：/)) skills[&#039;技術&#039;] = extractSkill(line);
    if (line.match(/知識：/)) skills[&#039;知識&#039;] = extractSkill(line);
    if (line.match(/怪異：/)) skills[&#039;怪異&#039;] = extractMultipleSkills(line);
    if (line.includes(&#039;恐怖心：&#039;)) fear = extractSkill(line);
    if (line.includes(&#039;：装備&#039;) || line.includes(&#039;：攻撃&#039;) || line.includes(&#039;：サポ&#039;)) {
      abilities.push(formatAbility(line));
    }
  }

  const output = `
------------------------------------------
👁️‍🗨️ 名前：${name}　PL：
------------------------------------------
⚜ 特技　★${special}
　暴力分野：${skills[&#039;暴力&#039;]}
　情動分野：${skills[&#039;情動&#039;]}
　知覚分野：${skills[&#039;知覚&#039;]}
　技術分野：${skills[&#039;技術&#039;]}
　知識分野：${skills[&#039;知識&#039;]}
★怪異分野：${skills[&#039;怪異&#039;].map(s =&gt; `〈${s}〉`).join(&#039;、&#039;)}

✖恐怖心：${fear}
------------------------------------------
💠 アビリティ
　${abilities.join(&#039;\n　&#039;)}
------------------------------------------
❤ 感情
　・PC名　→　感情(+/-)
　
------------------------------------------
📓 情報/居所
　・
　
------------------------------------------
------------------------------------------

`.trim();

  document.getElementById(&#039;output&#039;).textContent = output;
}
function extractSkill(line) {
  const match = line.match(/：(.+)/);
  if (!match) return &#039;〈〉&#039;;

  const raw = match[1]
    .replace(/[〈〉]/g, &#039;&#039;)       // 括弧除去
    .replace(/○：?/g, &#039;&#039;)        // 習得マーク除去
    .replace(/：/g, &#039;&#039;)          // 残ったコロン除去
    .trim();

  if (!raw) return &#039;〈〉&#039;;

  const parts = raw.split(/、|,/).map(s =&gt; s.trim()).filter(Boolean);
  return parts.map(p =&gt; `〈${p}〉`).join(&#039;、&#039;);
}

function extractMultipleSkills(line) {
  const match = line.match(/怪異：○：(.+)/);
  return match ? match[1].split(&#039;、&#039;).map(s =&gt; s.trim().replace(/[〈〉]/g, &#039;&#039;)) : [];
}

function formatAbility(line) {
  const parts = line.split(&#039;：&#039;);
  const name = parts[0].trim();
  const type = parts[1].trim();
  const skill = parts[2] ? parts[2].trim().replace(/[〈〉]/g, &#039;&#039;) : &#039;&#039;;
  return `【　${name}　】：　${type}　：　〈${skill || &#039;なし&#039;}〉`;
}

function copyOutput() {
  const text = document.getElementById(&#039;output&#039;).textContent;
  navigator.clipboard.writeText(text).then(() =&gt; {
    alert(&#039;コピーしました！&#039;);
  }).catch(err =&gt; {
    alert(&#039;コピーに失敗しました…🌀&#039;);
    console.error(err);
  });
}
